import { createLogger } from '../utils/logger';
import { z } from 'zod';

const log = createLogger('AccessTokenRefresh');

export const getJwtSub = (accessToken: string): string | null => {
  if (!accessToken) {
    return null;
  }
  try {
    const segment = accessToken.split('.')[1];
    if (!segment) {
      return null;
    }
    const normalized = segment.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=');
    const decoded = JSON.parse(
      Buffer.from(padded, 'base64').toString('utf8'),
    ) as {
      sub?: string;
    };
    return typeof decoded.sub === 'string' && decoded.sub.length > 0
      ? decoded.sub
      : null;
  } catch {
    return null;
  }
};

export const getJwtDisplayName = (accessToken: string): string | null => {
  if (!accessToken) {
    return null;
  }
  try {
    const segment = accessToken.split('.')[1];
    if (!segment) {
      return null;
    }
    const normalized = segment.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=');
    const decoded = JSON.parse(
      Buffer.from(padded, 'base64').toString('utf8'),
    ) as {
      user_metadata?: { full_name?: unknown; name?: unknown };
    };
    const candidate =
      decoded.user_metadata?.full_name ?? decoded.user_metadata?.name;
    return typeof candidate === 'string' && candidate.trim().length > 0
      ? candidate.trim()
      : null;
  } catch {
    return null;
  }
};

const RefreshResponseSchema = z.object({
  success: z.boolean().optional(),
  token: z.string().min(1).optional(),
  refreshToken: z.string().min(1).optional(),
});

export const refreshAccessTokenViaProxy = async (params: {
  refreshToken: string;
  proxyUrl: string;
  fetchImpl?: typeof fetch;
}): Promise<{ token: string; refreshToken?: string } | null> => {
  const fetchFn = params.fetchImpl ?? fetch;
  const base = params.proxyUrl.replace(/\/$/, '');
  try {
    const response = await fetchFn(`${base}/api/auth/refresh`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken: params.refreshToken }),
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      log.warn('Proxy token refresh returned non-OK status', {
        status: response.status,
      });
      return null;
    }
    const result = RefreshResponseSchema.safeParse(await response.json());
    if (!result.success) return null;
    if (result.data.success && result.data.token) {
      return {
        token: result.data.token,
        refreshToken: result.data.refreshToken,
      };
    }
    return null;
  } catch {
    log.warn('Proxy token refresh request failed');
    return null;
  }
};
